#include <stdio.h>

int main(void) {
    int marks = 55, day = 3;
    if (marks >= 75) printf("Distinction\n");
    else if (marks >= 40) printf("Pass\n");
    else printf("Try again\n");

    switch (day) {
        case 1: printf("Mon\n"); break;
        case 2: printf("Tue\n"); break;
        case 3: printf("Wed\n"); break;
        default: printf("Other\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int sum = 0;
    for (int i = 1; i <= 5; i++) {
        sum += i;
    }
    int n = 3;
    do {
        printf("%d ", n);
        n--;
    } while (n > 0);
    printf("\nsum=%d\n", sum);
    return 0;
}

#include <stdio.h>

int add(int a, int b);
void bump(int x);
void bump_ptr(int *x);

int main(void) {
    int n = 5;
    bump(n);
    printf("%d\n", n);
    bump_ptr(&n);
    printf("%d %d\n", n, add(2, 3));
    return 0;
}

int add(int a, int b) { return a + b; }
void bump(int x) { x++; }
void bump_ptr(int *x) { (*x)++; }

#include <stdio.h>

unsigned long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int main(void) {
    printf("%llu\n", factorial(5));
    return 0;
}

#include <stdio.h>

int main(void) {
    int marks[3] = {70, 80, 90};
    int count = sizeof(marks) / sizeof(marks[0]);
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += marks[i];
    }
    printf("%d items, total %d\n", count, total);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char name[20] = "LearnMate";
    char copy[20];
    snprintf(copy, sizeof copy, "%s", name);
    printf("%s %zu\n", copy, strlen(copy));
    if (strcmp(name, copy) == 0) {
        printf("equal\n");
    }
    return 0;
}

