#include <stdio.h>

int sum(const int *a, size_t n) {
    int total = 0;
    for (size_t i = 0; i < n; i++) {
        total += a[i];
    }
    return total;
}

int main(void) {
    int v[4] = {10, 20, 30, 40};
    int *p = v;
    printf("%d %d %d\n", v[2], *(p + 2), p[2]);
    printf("%d\n", sum(v, sizeof v / sizeof v[0]));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *p = malloc(5 * sizeof *p);
    if (p == NULL) {
        return 1;
    }
    for (int i = 0; i < 5; i++) {
        p[i] = i * i;
    }
    printf("%d\n", p[4]);
    free(p);
    p = NULL;
    return 0;
}

#include <stdio.h>

struct Student {
    int id;
    char grade;
};

enum Color { RED, GREEN, BLUE };

int main(void) {
    struct Student s = {1, 'A'};
    struct Student *p = &s;
    p->id = 2;
    printf("%d %c %d\n", s.id, s.grade, GREEN);
    return 0;
}

